'use strict';
const $=s=>document.querySelector(s),W=NullisWallet;
const state={provider:null,address:null,chainId:null,walletName:'',rows:[],warnings:[],loading:false,error:'',epoch:0,discovery:false,custom:[],hidden:false};
const providers=new Map();let listeners=null,abort=null,connecting=false,mode='',toastTimer;
const short=a=>a.slice(0,6)+'…'+a.slice(-4);
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function onChain(){try{return BigInt(state.chainId)===4663n}catch{return false}}
function page(p){if(!['swap','profile'].includes(p))p='swap';document.querySelectorAll('.page').forEach(e=>e.hidden=e.id!==p);document.querySelectorAll('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===p));if(location.hash!=='#'+p)location.hash=p}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));window.onhashchange=()=>page(location.hash.slice(1));page(location.hash.slice(1)||'swap');
function renderWallet(){
$('#wallet').textContent=state.address?short(state.address):'Connect wallet';$('#username').textContent='Your NULLIS profile';$('.identity p').textContent=state.address?`${short(state.address)} · ${onChain()?'Robinhood Chain':'Switch network'}`:'Connect a wallet to get started';$('#total').replaceChildren(node('span','Shielded account not created'));$('.portfolio-label').firstChild.textContent='NULLIS BALANCE ';$('#assets').replaceChildren(node('p','No assets deposited. Private accounts and settlement are in development.','empty'));$('.assets-heading>span').textContent='0 assets';$('#activity').textContent='No NULLIS transactions yet.';$('.activity-heading>span').textContent='';$('#sell-balance').textContent='NULLIS balance: —';$('#sell-usd').textContent='';$('#buy-usd').textContent='';$('#buy-amount').value='';$('#rate').textContent='Live quotes are not connected';$('.quote>span:last-child').textContent='';$('#swap-submit').textContent='Swaps coming soon';$('#swap-submit').disabled=true;$('.card-foot').textContent='Private swap infrastructure is in development.';$('#edit-name').textContent='Account setup coming soon';$('#edit-name').disabled=true;$('#copy-name').disabled=true;$('#copy-name').setAttribute('aria-label','Username not registered');$('[data-action="send"]').disabled=true;$('[data-action="withdraw"]').disabled=true;$('.profile-note').textContent='Wallet balances are public. Connecting a wallet does not create a private NULLIS account.';$('.network').textContent='ROBINHOOD CHAIN / WALLET INTEGRATION';$('footer>span:last-child').textContent='Read-only wallet integration';if($('#modal').open){if(mode==='wallet')walletFields();if(mode==='deposit')depositFields()}}
function invalidate(){state.epoch++;abort?.abort();state.rows=[];state.warnings=[];state.error='';state.loading=false}
function detach(){if(listeners&&state.provider?.removeListener)for(const [event,fn]of Object.entries(listeners))state.provider.removeListener(event,fn);listeners=null}
function disconnect(){detach();invalidate();state.provider=null;state.address=null;state.chainId=null;state.walletName='';state.custom=[];state.discovery=false;render();toast('Disconnected from NULLIS. Wallet permissions can be revoked in your wallet.')}
function watch(p){const accountsChanged=accounts=>{invalidate();state.custom=[];if(!W.isAddress(accounts?.[0])){disconnect();return}state.address=accounts[0];render();syncChain()};const chainChanged=chain=>{invalidate();state.chainId=chain;render();if(onChain())refresh()};listeners={accountsChanged,chainChanged,disconnect:disconnect};if(p.on)for(const [event,fn]of Object.entries(listeners))p.on(event,fn)}
async function syncChain(){const p=state.provider,epoch=state.epoch;try{const chain=await p.request({method:'eth_chainId'});if(p!==state.provider||epoch!==state.epoch)return;state.chainId=chain;render();if(onChain())await refresh()}catch(e){if(epoch===state.epoch){state.error=W.explain(e);render()}}}
async function refresh(){if(!state.provider||!state.address||!onChain()||state.loading)return;const epoch=++state.epoch,p=state.provider,address=state.address;abort?.abort();abort=new AbortController();state.loading=true;state.error='';state.rows=[];state.warnings=[];render();try{const result=await W.balances(p,address,{discoverTokens:state.discovery,custom:state.custom,signal:abort.signal});if(epoch!==state.epoch||p!==state.provider)return;state.rows=result.rows;state.warnings=result.warnings}catch(e){if(epoch===state.epoch)state.error=W.explain(e)}finally{if(epoch===state.epoch){state.loading=false;render()}}}
function addProvider(detail){if(!detail?.provider?.request)return;const id=typeof detail.info?.uuid==='string'?detail.info.uuid:'legacy';if([...providers.values()].some(x=>x.provider===detail.provider))return;providers.set(id,{provider:detail.provider,name:String(detail.info?.name||'Browser wallet').slice(0,60)});if($('#modal').open&&mode==='wallet')walletFields()}
window.addEventListener('eip6963:announceProvider',e=>addProvider(e.detail));
function discoverWallets(){window.dispatchEvent(new Event('eip6963:requestProvider'));if(window.ethereum?.request&&!providers.size)addProvider({provider:window.ethereum,info:{uuid:'legacy',name:'Browser wallet'}})}
discoverWallets();window.addEventListener('ethereum#initialized',discoverWallets);
async function connectWallet(entry){if(connecting)return;connecting=true;const epoch=state.epoch;state.error='';walletFields();try{const result=await W.connect(entry.provider);if(epoch!==state.epoch)return;detach();invalidate();state.provider=entry.provider;state.address=result.address;state.chainId=result.chainId;state.walletName=entry.name;watch(entry.provider);page('profile');render();open('profile');if(onChain())await refresh()}catch(e){state.error=W.explain(e)}finally{connecting=false;render()}}
function button(text,fn,cls='secondary'){const b=node('button',text,cls);b.type='button';b.onclick=fn;return b}
function walletFields(){const fields=$('#modal-fields');fields.replaceChildren();$('#confirm-action').hidden=true;$('#modal-title').textContent=state.address?'Connected wallet':'Connect wallet';$('#modal-description').textContent='Read-only connection. No signature, token approval, or transfer is requested. Balance reads use your wallet’s RPC provider.';if(state.address){fields.append(node('p',state.walletName+' · '+state.address,'wallet-address'),node('p',onChain()?'Robinhood Chain connected':'Your wallet is on another network. Switch to read Robinhood Chain balances.'));if(!onChain())fields.append(button('Switch to Robinhood Chain',switchNetwork,'primary'));fields.append(button('View wallet assets',()=>open('deposit'),'primary'),button('Choose another wallet',()=>{disconnect();discoverWallets();walletFields()}),button('Disconnect',disconnect))}else{if(!providers.size)fields.append(node('p','No browser wallet detected. Open this app in a browser with an EVM wallet extension, or in a wallet’s dapp browser. WalletConnect QR support is not connected yet.','wallet-hint'));for(const entry of providers.values()){const b=button(connecting?'Waiting for wallet…':entry.name,()=>connectWallet(entry),'wallet-choice');b.disabled=connecting;fields.append(b)}fields.append(button('Refresh wallet list',()=>{discoverWallets();walletFields()}))}$('#form-error').textContent=state.error}
async function switchNetwork(){const p=state.provider;if(!p)return;state.error='';try{await W.switchChain(p);if(p===state.provider)await syncChain()}catch(e){state.error=W.explain(e);render()}}
function depositFields(){
$('#modal-title').textContent='Deposit into NULLIS';$('#modal-description').textContent='Your external wallet assets appear here. Deposits will open once the shielded contracts are ready.';$('#confirm-action').hidden=false;$('#confirm-action').disabled=true;$('#confirm-action').textContent='Deposits coming soon';const fields=$('#modal-fields');fields.replaceChildren();if(!state.address){fields.append(button('Connect wallet',()=>open('wallet'),'primary'));return}fields.append(node('p',short(state.address)+' · external wallet','wallet-address'));if(!onChain()){fields.append(button('Switch to Robinhood Chain',switchNetwork,'primary'));$('#form-error').textContent=state.error;return}
const label=node('label',undefined,'discovery-option'),checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=state.discovery;checkbox.disabled=state.loading;checkbox.onchange=()=>{state.discovery=checkbox.checked;refresh()};label.append(checkbox,document.createTextNode('Discover more tokens with Blockscout'));fields.append(label,node('p','Optional discovery sends your public wallet address to Robinhood Chain’s Blockscout explorer. Results can be incomplete; token names do not prove authenticity.','wallet-hint'));const retry=button(state.loading?'Loading balances…':'Refresh balances',refresh);retry.disabled=state.loading;fields.append(retry);if(state.loading)fields.append(node('p','Reading Robinhood Chain balances…','wallet-hint'));
if(state.rows.length){const selectLabel=node('label','Choose an asset'),select=document.createElement('select');select.id='wallet-asset';for(const t of state.rows){const option=node('option',`${t.symbol} — ${state.hidden?'••••':t.balance}${t.verified?' · canonical':''}`);option.value=t.address||'ETH';select.append(option)}selectLabel.append(select);fields.append(selectLabel);const detail=node('p',undefined,'wallet-address');function selected(){const t=state.rows.find(t=>(t.address||'ETH')===select.value);detail.textContent=t?(t.address||'Native ETH')+(t.verified?'':' · Unverified token'):''}select.onchange=selected;selected();fields.append(detail,node('p','Balances are read from the chain. USD prices and shielded balances are not available.','wallet-hint'))}
for(const warning of state.warnings)fields.append(node('p',warning,'wallet-hint'));const tokenLabel=node('label','Missing token? Add its contract address'),tokenInput=document.createElement('input');tokenInput.id='custom-token';tokenInput.placeholder='0x…';tokenInput.autocomplete='off';tokenLabel.append(tokenInput);fields.append(tokenLabel);const add=button('Read token balance',async()=>{const address=tokenInput.value.trim();if(!W.isAddress(address)){$('#form-error').textContent='Enter a valid token contract address.';return}const epoch=state.epoch,p=state.provider;add.disabled=true;$('#form-error').textContent='';try{const token=await W.metadata(p,address);if(epoch!==state.epoch||p!==state.provider)return;if(!state.custom.some(t=>t.address.toLowerCase()===address.toLowerCase()))state.custom.push(token);await refresh()}catch{if(epoch===state.epoch)$('#form-error').textContent='Could not read that ERC-20 contract. Check the address and network.'}finally{add.disabled=false}});add.disabled=state.loading;fields.append(add);$('#form-error').textContent=state.error;
}
function openWallet(next){mode=next;$('#form-error').textContent='';if(!$('#modal').open)$('#modal').showModal();if(mode==='wallet'){discoverWallets();walletFields()}else if(mode==='deposit'){depositFields();if(!state.rows.length&&!state.loading)refresh()}}
$('#wallet').onclick=()=>open('wallet');$('[data-action="deposit"]').onclick=()=>open(state.address?'deposit':'wallet');$('#close-modal').onclick=()=>$('#modal').close();$('#action-form').onsubmit=e=>e.preventDefault();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('#settings').onclick=()=>$('#settings-panel').hidden=!$('#settings-panel').hidden;$('#reverse').onclick=()=>{const s=$('#sell-token').value;$('#sell-token').value=$('#buy-token').value;$('#buy-token').value=s};$('#hide-balances').onclick=()=>{state.hidden=!state.hidden;$('#hide-balances').setAttribute('aria-label',state.hidden?'Show balances':'Hide balances');render()};

